{"source":"import odoolib,json
c=odoolib.get_connection(hostname='127.0.0.1',protocol='json2',port=8069,database='bench',password=open('/etc/odoo/api_key').read().strip())
def q(m,d,f): return c.get_model(m).search_read(domain=d,fields=f,limit=1000)
for m in ['mrp.workcenter','product.product','product.template','mrp.bom','purchase.order.line','product.supplierinfo','res.partner']:
 try:
  print('FIELDS',m, json.dumps(list(c.get_model(m).fields_get().keys())))
 except Exception as e: print('ERRFIELDS',m,str(e))
print('PRODUCT',json.dumps(q('product.product',[('id','=',2)],['id','name','default_code','qty_available','list_price','product_tmpl_id']),default=str))
print('WORKCENTERS',json.dumps(q('mrp.workcenter',[],['id','name','note','capacity','time_start','time_stop']),default=str))
print('MOs',json.dumps(q('mrp.production',[],['id','name','product_id','product_qty','state','origin','date_start','date_finished','workorder_ids']),default=str))
print('WOs',json.dumps(q('mrp.workorder',[],['id','production_id','workcenter_id','duration_expected','state']),default=str))
print('POL',json.dumps(q('purchase.order.line',[],['id','order_id','product_id','product_qty','price_unit','date_planned']),default=str))
print('SUP',json.dumps(q('product.supplierinfo',[],['id','partner_id','product_tmpl_id','product_id','min_qty','price','delay']),default=str))
print('VENDORS',json.dumps(q('res.partner',[('supplier_rank','>',0)],['id','name','comment']),default=str))
print('BOM',json.dumps(q('mrp.bom',[],['id','product_tmpl_id','product_id','product_qty','bom_line_ids']),default=str))
print('BOMLINES',json.dumps(q('mrp.bom.line',[],['id','bom_id','product_id','product_qty']),default=str))"}
